import random

target = "......((.......((.((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...............)).......)).((.......((.((...............)).........((...............)).)).......)).((.......((...........((...............)).)).......)).)).......))......"
n = len(target)

def get_pairs(struct):
    stack=[]
    pairs={}
    for i,c in enumerate(struct):
        if c=='(':
            stack.append(i)
        elif c==')':
            j=stack.pop()
            pairs[j]=i
            pairs[i]=j
    return pairs

pairs = get_pairs(target)

def build(seed, gc_bias=0.7):
    rng = random.Random(seed)
    seq = [None]*n
    gc_opts = [('G','C'), ('C','G')]
    au_opts = [('A','U'), ('U','A')]
    gu_opts = [('G','U'), ('U','G')]
    for i in range(n):
        if seq[i] is not None: continue
        if target[i]=='(':
            j = pairs[i]
            r = rng.random()
            if r < gc_bias:
                a,b = rng.choice(gc_opts)
            elif r < gc_bias + 0.25:
                a,b = rng.choice(au_opts)
            else:
                a,b = rng.choice(gu_opts)
            seq[i]=a
            seq[j]=b
    for i in range(n):
        if seq[i] is None:
            seq[i] = rng.choice(['A','A','A','C','U','G'])
    return ''.join(seq)

for seed in range(2000):
    gc_bias = 0.5 + 0.4*random.Random(seed+99999).random()
    s = build(seed, gc_bias)
    print(s)
